// Real current-main state and combat contracts, not OS input or a natural battle simulation.
using System;using System.IO;using System.Linq;using System.Reflection;using ReversalTower;using UnityEngine;
public static class SelectiveIntegrationTests {
 static int n;static void Check(bool x,string name){if(!x)throw new Exception(name);n++;Console.WriteLine("PASS "+name);}
 static object Call(TowerGame g,string name,params object[] args)=>typeof(TowerGame).GetMethod(name,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(g,args);
 static TowerGame Game(SaveData s){var g=new TowerGame{save=s};typeof(TowerGame).GetField("sound",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(g,new Soundscape());return g;}
 static void Complete(TutorialSession t,int failures,int extra){long id=1;t.Tick(11,false);t.Tick(7,true);for(int i=0;i<6;i++)t.Acknowledge();foreach(var a in new[]{TutorialAction.Q,TutorialAction.W,TutorialAction.E,TutorialAction.Move,TutorialAction.Jump,TutorialAction.Attack,TutorialAction.Dash}){t.Acknowledge();t.Tick(1,false);t.ConfirmAction(a,true);}t.Acknowledge();t.ConfirmAction(TutorialAction.Potion,true,10);t.Acknowledge();t.Acknowledge();for(int i=0;i<failures;i++)t.ResolveThreat(id++,true,true,false,true);t.ResolveThreat(id++,true,true,true,false,true);Check(t.AwaitingThreatFeedback,"main feedback gate retained");float active=t.Assessment.activeDurationSeconds;t.Tick(2,false,true);Check(t.Assessment.activeDurationSeconds==active&&t.Assessment.explanationSeconds==13,"feedback excluded from active and included in instruction clock");t.CompleteThreatFeedback();t.Acknowledge();for(int i=0;i<failures;i++)t.ResolveThreat(id++,false,true,false,true);t.ResolveThreat(id++,false,true,true,false);t.Acknowledge();for(int i=0;i<extra;i++)t.ResolveThreat(id++,true,true,true,false);t.GaugeChanged(100);t.Acknowledge();t.ConfirmAction(TutorialAction.Ultimate,true);t.ConfirmEmpoweredSwordHit(true,true);}
 public static int Main(){string root=Path.Combine(Path.GetTempPath(),"dda-selective-"+Guid.NewGuid().ToString("N"));
 try{CommunityStats.Replace(new CommunityStats.Entry[0]);CommunityStats.ReplaceGroups(new CommunityStats.Entry[0]);
 foreach(string group in new[]{"novice","normal","expert"}){SaveStore.UseIsolatedRoot(Path.Combine(root,group));var g=Game(SaveStore.Load());g.StartTutorial(false);Complete(g.Tutorial,group=="novice"?8:group=="normal"?1:0,group=="novice"?0:2);Check(g.Tutorial.Assessment.group==group,"actual tutorial rules classify "+group);Call(g,"FinishTutorial");Check(!g.TutorialActive&&g.save.tutorialAssessment.group==group&&SaveStore.Load().tutorialAssessment.valid,"completion persists initial assessment "+group);var completedProfile=g.save;g.save=new SaveData();Check(g.LastTutorialAssessment==null,"profile switch cannot display old assessment "+group);g.save=completedProfile;g.StartBattle(0);int level=group=="novice"?-1:group=="expert"?1:0;Check(g.Stat("cleave").level==level,"first real battle applies tutorial "+group);for(int i=0;i<20;i++){g.playerInv=0;g.parryAge=.1f;g.PlayerHit(1,true,"cleave",g.boss.x);}Check(g.Stat("cleave").opportunities==20&&g.Stat("cleave").parries==20,"actual PlayerHit records parries "+group);g.DamageBoss(g.bossHp);Check(g.save.Learning("arakus").battles==1&&g.save.Learning("arakus").Pattern("cleave").observations==1,"actual battle settlement learns once "+group);string learning=JsonUtility.ToJson(g.save.learning);var loaded=SaveStore.Load();Check(learning==JsonUtility.ToJson(loaded.learning)&&loaded.tutorialAssessment.group==group,"model and assessment survive reload "+group);g=Game(loaded);g.StartBattle(0);Check(g.Stat("cleave").level==level+1,"next battle uses personal high-response progression "+group);Check(Directory.GetFiles(Path.Combine(SaveStore.Root,"DdaLearning"),"*.json").Length==1,"settlement writes learning trace "+group);}
 SaveStore.UseIsolatedRoot(Path.Combine(root,"main"));var main=Game(new SaveData{tutorialOnboardingVersion=1,unlockedBoss=4,gold=1000});SaveStore.Save(main.save);main.StartTutorial(true);main.showSettings=true;Call(main,"CloseSettings");Check(main.TutorialActive&&!main.showSettings&&SaveStore.Load().gold==1000,"real main settings saves original profile during detached tutorial");main.ExitTutorial();Application.isPlaying=true;main.StartBattle(1);Check(main.TransitionActive,"main transition queues battle");Call(main,"TickTransition",1f);Call(main,"TickTransition",1f);Application.isPlaying=false;Check(main.mode==ScreenMode.Battle&&main.spec.id=="phanes","transition enters intended boss");var star=main.spec.patterns.Single(x=>x.id==BossPatternSystem.PhanesUltimate);main.Stat(star.id).level=1;main.BossPatterns.BeginPattern(star);var live=main.DdaSnapshot();Check(live.pattern==star.id&&live.level==1&&live.windup==star.windup&&live.damage==main.BossPatterns.patternDamage,"snapshot preserves main Phanes special timing and actual damage");main.save.equippedUltimate=1;main.ult=100;Call(main,"BeginAction","R",.85f);Call(main,"TickAction",.3f);Check(main.shots.Count(s=>s.friendly&&s.pattern=="ultimate")==5,"main inherited Phanes R retains five friendly stars");
 Console.WriteLine("SELECTIVE_INTEGRATION_PASS "+n);return 0;
 }finally{Application.isPlaying=false;SaveStore.UseIsolatedRoot(null);if(Directory.Exists(root))Directory.Delete(root,true);}}
}
